namespace ghidra.app.plugin.core.debug.gui.model;



using org.apache.commons.lang3;

using ghidra.trace.model.target;
using ghidra.trace.model.target;
using ghidra.trace.model.target.iface;
using ghidra.util;
using ghidra.util;

public interface DisplaysObjectValues {
	long getSnap();

	string getNullDisplay() {
		return "";
	}

	string getBoolsDisplay(bool[] bools) {
		return Stream.of(ArrayUtils.toObject(bools))
				.map(b => b ? "T" : "F")
				.collect(Collectors.joining(":"));
	}

	string getBytesDisplay(byte[] bytes) {
		return NumericUtilities.convertBytesToString(bytes, ":");
	}

	string getCharsDisplay(char[] chars) {
		return new string(chars);
	}

	string getShortsDisplay(short[] shorts) {
		return Stream.of(ArrayUtils.toObject(shorts))
				.map(s => "%04x".formatted(s))
				.collect(Collectors.joining(":"));
	}

	string getIntsDisplay(int[] ints) {
		return IntStream.of(ints)
				.mapToObj(i => "%08x".formatted(i))
				.collect(Collectors.joining(":"));
	}

	string getLongsDisplay(long[] longs) {
		return LongStream.of(longs)
				.mapToObj(l => "%016x".formatted(l))
				.collect(Collectors.joining(":"));
	}

	string getStringsDisplay(string[] strings) {
		return Stream.of(strings)
				.collect(Collectors.joining(":"));
	}

	string getPrimitiveValueDisplay(object value) {
		System.Diagnostics.Debug.Assert(!(value is TraceObject));
		System.Diagnostics.Debug.Assert(!(value is TraceObjectValue));
		// TODO: Choose decimal or hex for integral types?
		if (value == null) {
			return getNullDisplay();
		}
		if (value is bool[] bools) {
			return getBoolsDisplay(bools);
		}
		if (value is byte[] bytes) {
			return getBytesDisplay(bytes);
		}
		if (value is char[] chars) {
			return getCharsDisplay(chars);
		}
		if (value is short[] shorts) {
			return getShortsDisplay(shorts);
		}
		if (value is int[] ints) {
			return getIntsDisplay(ints);
		}
		if (value is long[] longs) {
			return getLongsDisplay(longs);
		}
		if (value is string[] strings) {
			return getStringsDisplay(strings);
		}
		return value.toString();
	}

	string getPrimitiveEdgeType(TraceObjectValue edge) {
		return edge.getTargetSchema().getName() + ":" + edge.getValue().GetType().getSimpleName();
	}

	string getPrimitiveEdgeToolTip(TraceObjectValue edge) {
		return getPrimitiveValueDisplay(edge.getValue()) + " (" + getPrimitiveEdgeType(edge) + ")";
	}

	string getObjectLinkDisplay(TraceObjectValue edge) {
		return getObjectDisplay(edge);
	}

	string getObjectType(TraceObjectValue edge) {
		TraceObject @object = edge.getChild();
		return @object.getSchema().getName().toString();
	}

	string getObjectLinkToolTip(TraceObjectValue edge) {
		return "Link to " + getObjectToolTip(edge);
	}

	string getRawObjectDisplay(TraceObjectValue edge) {
		TraceObject @object = edge.getChild();
		if (@object.isRoot()) {
			return "<root>";
		}
		return @object.getCanonicalPath().toString();
	}

	string getObjectDisplay(TraceObjectValue edge) {
		TraceObject @object = edge.getChild();
		TraceObjectValue displayAttr =
			@object.getAttribute(getSnap(), TraceObjectInterface.KEY_DISPLAY);
		if (displayAttr != null) {
			return displayAttr.getValue().toString();
		}
		return getRawObjectDisplay(edge);
	}

	string getObjectToolTip(TraceObjectValue edge) {
		string display = getObjectDisplay(edge);
		string raw = getRawObjectDisplay(edge);
		if (display.equals(raw)) {
			return display + " (" + getObjectType(edge) + ")";
		}
		return display + " (" + getObjectType(edge) + ":" + raw + ")";
	}

	string getEdgeDisplay(TraceObjectValue edge) {
		if (edge == null) {
			return "";
		}
		if (edge.isCanonical()) {
			return getObjectDisplay(edge);
		}
		if (edge.isObject()) {
			return getObjectLinkDisplay(edge);
		}
		return getPrimitiveValueDisplay(edge.getValue());
	}

	/**
	 * Get an HTML string representing how the edge's value should be displayed
	 * 
	 * @return the display string
	 */
	string getEdgeHtmlDisplay(TraceObjectValue edge) {
		if (edge == null) {
			return "";
		}
		if (!edge.isObject()) {
			return "<html>" +
				HTMLUtilities.escapeHTML(getPrimitiveValueDisplay(edge.getValue()), true);
		}
		if (edge.isCanonical()) {
			return "<html>" + HTMLUtilities.escapeHTML(getObjectDisplay(edge), true);
		}
		return "<html><em>" + HTMLUtilities.escapeHTML(getObjectLinkDisplay(edge), true) + "</em>";
	}

	string getEdgeToolTip(TraceObjectValue edge) {
		if (edge == null) {
			return null;
		}
		if (edge.isCanonical()) {
			return getObjectToolTip(edge);
		}
		if (edge.isObject()) {
			return getObjectLinkToolTip(edge);
		}
		return getPrimitiveEdgeToolTip(edge);
	}
}
